-- Fill missing admin fields from the already-published editorial estate pages.
-- Preserve authored values and revision history; record the complete before-image.
CREATE TABLE IF NOT EXISTS estate_content_repair_20260906 (estate_id uuid PRIMARY KEY,before_row jsonb NOT NULL,repaired_at timestamptz NOT NULL DEFAULT now());
DO $repair$
DECLARE item jsonb; live estates%ROWTYPE; prior cms_content_revisions%ROWTYPE; patch jsonb; next_version integer;
BEGIN
 FOR item IN SELECT value FROM jsonb_array_elements($content$[{"slug":"bellagio","description":"碧堤半島位於深井青山公路深井段，屋苑規模大、臨海感強，是深井最具代表性的換樓屋苑之一。\n\n買家通常會比較座向、期數、海景開揚度、會所距離和往返荃灣的交通安排。","transport_note":"小巴及巴士接駁荃灣、九龍、港島和機場方向，日常生活依靠深井商店、餐飲和鄰近屋苑配套。"},{"slug":"sea-crest-villa","description":"浪翠園分期發展，屋苑規模大，單位選擇由上車面積至家庭三房都有。\n\n買家會重點比較期數、樓齡、景觀、裝修和與巴士小巴站的距離。","transport_note":"屋苑依靠青山公路巴士及小巴接駁荃灣，生活配套與深井餐飲、超市和鄰近屋苑共用。"},{"slug":"hong-kong-garden","description":"豪景花園位於青龍頭，屋苑規模大，常被買家用來比較深井核心屋苑以外的空間型選擇。\n\n買家通常重視實用面積、景觀、交通時間和屋苑內外配套。","transport_note":"主要依靠青山公路交通往返荃灣、屯門和機場方向，適合能接受巴士小巴或自駕的家庭。"},{"slug":"rhine-garden","description":"海韻花園位處深井臨海地段，景觀和寧靜感是主要吸引點。\n\n買家會重點比較海景開揚度、樓層、裝修、管理和與深井核心配套的距離。","transport_note":"日常可使用深井青山公路交通和生活配套，適合接受非鐵路步行生活圈的住戶。"},{"slug":"lido-garden","description":"麗都花園位於深井青山公路深井段，屋苑成熟，鄰近深井餐飲和日常配套。\n\n對買家和租客而言，麗都花園的優勢在於生活便利、入場門檻和深井核心位置。","transport_note":"鄰近深井主要商店、餐飲和青山公路交通，適合想住在深井核心生活圈的買家和租客。"},{"slug":"hoi-wan-hin","description":"海雲軒位於青山公路近釣魚灣一帶，由兩座住宅組成；買家通常先比較座向、海景開揚度、樓層、裝修和車位。\n\n相對深井大型屋苑，海雲軒盤源較少，睇樓時宜把同類單位和鄰近屋苑放在同一天比較。","transport_note":"主要透過青山公路巴士、小巴及自駕往返荃灣、九龍及港島方向；實際路線與班次以營辦商最新公布為準。"},{"slug":"tai-wah-hin","description":"帝華軒是浪翠園第 5 期，市場亦以 Royal Sea Crest 或 Sea Crest Villa Phase 5 搜尋。\n\n單位以大三房為主，睇樓重點包括景觀、露台、裝修、車位，以及與浪翠園其他期數的管理和位置差異。","transport_note":"主要依靠青山公路及龍騰路一帶巴士、小巴或自駕往返荃灣及市區；睇樓時應實測繁忙時間接駁。"},{"slug":"hoi-wan-toi","description":"海韻臺位於青山公路深井段，市場上亦常寫作「海韻台」；它與附近的海韻花園是兩個不同屋苑。\n\n買家通常比較高低層景觀、座向、裝修，以及單幢管理與大型屋苑會所和盤源量之間的取捨。","transport_note":"可利用青山公路巴士、小巴和自駕接駁荃灣及市區；日常購物與餐飲可使用深井生活圈配套。"},{"slug":"chun-wong-kui","description":"縉皇居位於深慈街，樓宇高度和臨海景觀是主要辨識點，單位由家庭戶至較大戶型都有。\n\n睇樓時應比較座數、方向、海景遮擋、樓層、裝修及升降機等候情況，而不是只看屋苑平均呎價。","transport_note":"主要以深井巴士、小巴及自駕接駁荃灣、九龍和港島方向，生活配套可使用深井商店、餐飲及鄰近屋苑商場。"},{"slug":"lung-tang-kok","description":"龍騰閣位於青山公路青龍頭段，單位面積大、總伙數少，是沿線較少見的低密度家庭住宅。\n\n成交量不高，買家應把單位狀況、景觀、車位、公共地方維修和大廈工程紀錄放在價格前一併評估。","transport_note":"日常主要靠青山公路巴士、小巴或自駕，睇樓時宜實測往返荃灣、深井和主要工作地點的繁忙時間。"},{"slug":"mun-ming-shan","description":"滿名山由分層住宅與洋房組成，戶型跨度大，買家要先確定滿庭、名庭或山庭等產品類型。\n\n分層、特色戶和洋房不可用同一平均數概括，成交與放盤應按產品、景觀、戶外空間和車位分開呈現。","transport_note":"主要透過掃管笏及青山公路巴士、小巴和自駕連接屯門、荃灣及市區；實際通勤應按個人時段試走。"},{"slug":"wong-gam-hoi-ngon","description":"香港黃金海岸分期發展，單位面積、樓齡、景觀和位置差異大，買家應先確定期數與戶型。\n\n屋苑鄰近海濱、商場及休閒配套，但各座往交通站點和生活設施的步行距離不同。","transport_note":"可使用青山公路巴士、小巴及自駕往返屯門、荃灣、九龍和港島方向；睇樓時要按座數實測接駁距離。"},{"slug":"oi-kam-hoi-ngon","description":"愛琴海岸由七座住宅組成，單位面積主要集中在兩至三房家庭戶，較容易以相近面積和座向比較成交。\n\n買家會重點比較高低層、海景或內園景、座數位置、裝修、車位及往交通站點的距離。","transport_note":"主要利用掃管笏及青山公路巴士、小巴和自駕往返屯門、荃灣及市區；實際路線和班次以最新營運資料為準。"},{"slug":"tai-yu","description":"帝御由金灣、星濤及嵐天三期組成，戶型由開放式至較大家庭單位，買家應先按期數和面積收窄選擇。\n\n三期的座數、落成年份、景觀和戶型組合不同；搜尋、成交和比較表應保留 phase 欄位。","transport_note":"主要使用青山公路沿線巴士、小巴及自駕，並可接駁屯門生活圈；實際交通時間應按出發時段測試。"},{"slug":"wong-gam-hoi-waan","description":"黃金海灣分為意嵐 The Uppland 與珀岸 The Reserve 兩期，產品由細面積單位至較大家庭戶，頁面必須按期數標示。\n\n項目較新，一手資料、已入伙二手放盤與註冊成交可能同時存在，資訊來源、日期和性質需清楚分開。","transport_note":"主要透過青山公路巴士、小巴及自駕接駁屯門、荃灣與市區；新路線或班次必須引用最新營運資料。"},{"slug":"sing-tai","description":"星堤由分層住宅與洋房組成，產品跨度大；買家應先決定分層、複式或洋房，再比較景觀、戶外空間和車位。\n\n低密度環境是主要賣點，但成交量和盤源會因產品類型而明顯不同，估值需要更多個案比較。","transport_note":"主要透過掃管笏及青山公路沿線交通接駁屯門、荃灣和市區；有車家庭仍需確認車位使用條款。"},{"slug":"seong-yuen","description":"上源由分層大廈和洋房組成，單位由一房至大型洋房，買家應按產品、座數、景觀和車位先行分類。\n\n部分平台把分層大廈按 A／B 子座計作十座，另有資料以五座大廈描述；頁面應顯示組成文字。","transport_note":"主要使用掃管笏路及青山公路巴士、小巴或自駕接駁屯門、荃灣及市區；睇樓時應按座數測試步行和等車時間。"},{"slug":"the-carmel","description":"The Carmel 由兩座分層住宅及多間洋房組成，供應由細面積單位至大型獨立屋，市場比較必須先分產品類型。\n\n屋苑總伙數較少，盤源與成交未必連續；睇樓時應確認車位、花園、天台、維修責任和管理費。","transport_note":"主要透過青山公路巴士、小巴及自駕連接屯門、荃灣和市區；洋房買家亦應核實車位數量和充電安排。"},{"slug":"oma-oma","description":"OMA OMA 由四座住宅組成，戶型由細面積單位延伸至較大家庭戶，買家應先按房數和實用間隔比較。\n\n樓齡較新是主要優點，但仍要評估景觀、道路聲、座數位置、收納、會所距離和交通接駁。","transport_note":"主要透過掃管笏路及青山公路巴士、小巴或自駕接駁屯門、荃灣與市區；實際步行與等車時間需按座數測試。"},{"slug":"lin-shan","description":"漣山位於青發里，由多座低密度住宅組成，單位面積較大，買家通常比較座數、景觀、樓層、平台或花園及車位。\n\n屋苑總伙數不多，短期成交樣本可能有限；樓齡、外牆及公共地方維修紀錄亦是重要盡職審查項目。","transport_note":"主要靠青山公路巴士、小巴或自駕接駁屯門、荃灣和市區；有車家庭應確認車位業權或使用安排。"},{"slug":"long-tou-waan","description":"浪濤灣由分層住宅及洋房組成，海景、戶外空間和低密度是主要特色；買家要先分清產品類型。\n\n睇樓重點包括景觀遮擋、海風及外牆狀況、花園或天台、車位、管理費和往主要交通站點的距離。","transport_note":"主要依靠青山公路巴士、小巴及自駕接駁屯門、荃灣和市區；有車家庭應確認車位和充電安排。"},{"slug":"tai-tou-waan","description":"帝濤灣分兩期發展，市場常以浪琴軒、海琴軒及相關英文名搜尋；買家必須先確認期數、座數和戶型。\n\n單位由兩房至較大家庭戶，景觀、樓層、車位、裝修與兩期位置差異會直接影響價格和租務。","transport_note":"主要利用青山公路巴士、小巴及自駕接駁屯門、荃灣與市區；應按實際座數測試步行和通勤。"}]$content$::jsonb) LOOP
  SELECT * INTO live FROM estates WHERE slug=item->>'slug';
  IF NOT FOUND THEN CONTINUE; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('cms:estate:'||live.id::text,0));
  SELECT * INTO live FROM estates WHERE id=live.id FOR UPDATE;
  patch='{}'::jsonb;
  IF nullif(trim(live.description),'') IS NULL THEN patch=patch||jsonb_build_object('description',item->>'description'); END IF;
  IF nullif(trim(live.transport_note),'') IS NULL THEN patch=patch||jsonb_build_object('transport_note',item->>'transport_note'); END IF;
  IF patch='{}'::jsonb THEN CONTINUE; END IF;
  INSERT INTO estate_content_repair_20260906(estate_id,before_row) VALUES(live.id,to_jsonb(live)) ON CONFLICT DO NOTHING;
  SELECT * INTO prior FROM cms_content_revisions WHERE resource_type='estate' AND resource_id=live.id AND state='published' FOR UPDATE;
  IF FOUND THEN
   SELECT coalesce(max(version_number),0)+1 INTO next_version FROM cms_content_revisions WHERE resource_type='estate' AND resource_id=live.id;
   UPDATE cms_content_revisions SET state='superseded' WHERE id=prior.id;
   INSERT INTO cms_content_revisions(resource_type,resource_id,state,version_number,payload,published_at,base_published_version,validation_summary)
   VALUES('estate',live.id,'published',next_version,prior.payload||patch,now(),prior.version_number,'{}'::jsonb);
  END IF;
  UPDATE estates SET description=coalesce(patch->>'description',description),transport_note=coalesce(patch->>'transport_note',transport_note),updated_at=now() WHERE id=live.id;
 END LOOP;
END $repair$;
